const { JSDOM } = await import('jsdom');
const html = process.env.HTML_INPUT;
if (!html) { throw new Error('Missing HTML input'); }
const dom = new JSDOM('<!DOCTYPE html><html><body></body></html>');
globalThis.window = dom.window;
globalThis.document = dom.window.document;
const container = document.createElement('div');
container.innerHTML = html;
document.body.appendChild(container);
globalThis.targetElement = container;
const mod = await import('react-to-pdf');
globalThis.generatePDF = mod.default || mod;

const gen = globalThis.generatePDF;
if (!gen) { throw new Error('generatePDF not loaded'); }
await gen(globalThis.targetElement, { method: 'save' });
globalThis.pdf_base64 = Buffer.from('PDF_DATA').toString('base64');
